import{_ as d,o as e,c as a,a2 as o}from"./chunks/framework.D66Xq0Kv.js";const b=JSON.parse('{"title":"JVM性能调优工具汇总","description":"","frontmatter":{"title":"JVM性能调优工具汇总","date":"2021-12-31","categories":["编程语言","Java"],"tags":["Java","JVM","性能调优"]},"headers":[],"relativePath":"编程语言/JVM性能调优工具汇总.md","filePath":"编程语言/JVM性能调优工具汇总.md"}'),r={name:"编程语言/JVM性能调优工具汇总.md"};function c(h,t,l,s,i,n){return e(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="jvm性能调优工具汇总" tabindex="-1">JVM性能调优工具汇总 <a class="header-anchor" href="#jvm性能调优工具汇总" aria-label="Permalink to &quot;JVM性能调优工具汇总&quot;">​</a></h1><h2 id="一命令行工具" tabindex="-1">一、命令行工具 <a class="header-anchor" href="#一命令行工具" aria-label="Permalink to &quot;一、命令行工具&quot;">​</a></h2><table tabindex="0"><thead><tr><th>序号</th><th>名称</th><th>功能</th></tr></thead><tbody><tr><td>1</td><td><code>jps</code></td><td>虚拟机进程状况工具，主要用于查找vmid，是后续命令的基础</td></tr><tr><td>2</td><td><code>jstat</code></td><td>虚拟机统计信息监视工具，查找虚拟机进程中类加载、内存、GC等信息</td></tr><tr><td>3</td><td><code>jinfo</code></td><td>Java配置信息工具，实时查看和调整虚拟机各项参数</td></tr><tr><td>4</td><td><code>jmap</code></td><td>Java内存映像工具，生成堆转储快照（headump、dump），与<code>jhat</code>配合使用</td></tr><tr><td>5</td><td><code>jhat</code></td><td>虚拟机堆转储快照分析工具，分析<code>jmap</code>生成的堆转储快照文件，与<code>jmap</code>配合使用</td></tr><tr><td>6</td><td><code>jstack</code></td><td>Java堆栈跟踪工具，生成虚拟机当前时刻的线程快照（threaddump、javacore）</td></tr><tr><td>7</td><td><code>jcmd</code></td><td>Java命令行工具集，整合了上述众多命令</td></tr><tr><td>8</td><td><code>clhsdb</code></td><td>HotSpot命令行调试器，也整合了上述众多命令</td></tr></tbody></table><blockquote><p>JDK9之后的变化：<code>jhat</code>与<code>clhsdb</code>被移除，<code>clhsdb</code>的功能被纳入了<code>jhsdb</code></p></blockquote><h2 id="二可视化工具" tabindex="-1">二、可视化工具 <a class="header-anchor" href="#二可视化工具" aria-label="Permalink to &quot;二、可视化工具&quot;">​</a></h2><table tabindex="0"><thead><tr><th>序号</th><th>名称</th><th>功能</th></tr></thead><tbody><tr><td>1</td><td><code>JHSDB</code></td><td>基于服务性代理的调试工具，JDK内置（从JDK9开始提供）</td></tr><tr><td>2</td><td><code>JConsole</code></td><td>Java监视与管理控制台，JDK内置</td></tr><tr><td>3</td><td><code>VisualVM</code></td><td>多合一故障处理工具，需要单独<a href="https://visualvm.github.io/" target="_blank" rel="noreferrer">下载</a></td></tr><tr><td>4</td><td><code>JMC</code></td><td>可持续在线的监控工具，需要单独<a href="https://www.oracle.com/javase/jmc/" target="_blank" rel="noreferrer">下载</a></td></tr></tbody></table><blockquote><p>参考文档</p></blockquote><ol><li>《深入理解Java虚拟机第3版 周志明 著》</li></ol>',8)])])}const m=d(r,[["render",c]]);export{b as __pageData,m as default};
